import { GameData } from "../../Core/Data/GameData";
import type { Entity } from "../../Engine/Entity";
import type { System } from "../../Engine/System";
import type { World } from "../../Engine/World";
import { BATTLE_EVENT } from "../BattleEvents";
import type { Bullet } from "../Entity/Bullet";
import type { Plane } from "../Entity/Plane";


interface GridCell {
    bullets: Bullet[];
    planes: Plane[];
    dirty: boolean;
}

interface CircleBody extends Entity {
    collisionRadius: number;
}


export class CombatSystem implements System {

    private _cellSize = 64;
    private _cols = 0;
    private _rows = 0;
    private _halfW = 0;
    private _halfH = 0;
    private _cells: GridCell[][] = [];
    private _dirtyCells: GridCell[] = [];

    onStart(world: World): void {
        this._halfW = GameData.viewW / 2;
        this._halfH = GameData.viewH / 2;
        // 网格覆盖屏幕范围，外扩 2 格
        this._cols = Math.ceil(GameData.viewW / this._cellSize) + 2;
        this._rows = Math.ceil(GameData.viewH / this._cellSize) + 2;

        // 预分配：一次性创建所有 cell，之后只复用不清空
        for (let c = 0; c < this._cols; c++) {
            this._cells[c] = [];
            for (let r = 0; r < this._rows; r++) {
                this._cells[c][r] = { bullets: [], planes: [], dirty: false };
            }
        }
    }

    onTick(world: World, dt: number): void {

        // 1. 清理上一帧用过的 cell（只清 dirty 的）
        for (let i = 0; i < this._dirtyCells.length; i++) {
            const cell = this._dirtyCells[i];
            cell.bullets.length = 0;
            cell.planes.length = 0;
            cell.dirty = false;
        }
        this._dirtyCells.length = 0;

        // 2. 插入子弹和敌机
        for(const b of world.query<Bullet>('bullet')){
            this._insertBullet(b);
        }
        for(const p of world.query<Plane>('enemy')){
            this._insertPlane(p);
        }
        for(const p of world.query<Plane>('player')){
            this._insertPlane(p);
        }

        //3.检测子弹碰撞
        for (const b of world.query<Bullet>('bullet')) {
            const targetKind = b.isPlayerBullet ? 'enemy' : 'player';
            this._checkBullet(b, targetKind, 
                (target) => {world.bus.emit(BATTLE_EVENT.BULLET_HIT,b,target);}
            );
        }

   }

    private _insertBullet(b: Bullet): void{
        const c = Math.floor((b.x + this._halfW) / this._cellSize);
        const r = Math.floor((b.y + this._halfH) / this._cellSize);
        if(!this._valid(c,r)){
            return;
        }
        const cell = this._cells[c][r];
        cell.bullets.push(b);
        this._markDirty(cell);
    }

    private _insertPlane(p: Plane): void {
        if (p.hp <= 0) return;
        const c = Math.floor((p.x + this._halfW) / this._cellSize);
        const r = Math.floor((p.y + this._halfH) / this._cellSize);
        if(!this._valid(c,r)){
            return;
        }
        const cell = this._cells[c][r];
        cell.planes.push(p);
        this._markDirty(cell);
    }

    private _markDirty(cell: GridCell): void{
        if(!cell.dirty){
            cell.dirty = true;
            this._dirtyCells.push(cell);
        }
    }

    private _checkBullet(b: Bullet, targetKind: 'player' | 'enemy', onHit: (target: Plane) => void): void {

        const c = Math.floor((b.x + this._halfW) / this._cellSize);
        const r = Math.floor((b.y + this._halfH) / this._cellSize);

        for (let dc = -1; dc <= 1; dc++) {
            for (let dr = -1; dr <= 1; dr++) {
                const cc = c + dc;
                const rr = r + dr;
                if (!this._valid(cc, rr)) continue;
                const cell = this._cells[cc][rr];
                for (let i = 0; i < cell.planes.length; i++) {
                    const p = cell.planes[i];
                    if (p.hp <= 0) continue;
                    if (p.kind !== targetKind) continue;
                    if (this._hit(b, p)) {
                        onHit(p);
                        return;   // 一颗子弹最多命中一个目标
                    }
                }
            }
        }
    }

    private _hit(a: CircleBody, b: CircleBody): boolean{
        const dx = a.x - b.x;
        const dy = a.y - b.y;
        const r = a.collisionRadius + b.collisionRadius;
        return dx * dx + dy * dy < r *  r
    }



    private _valid(c: number, r: number): boolean{
        return c >= 0 && c < this._cols && r >= 0 && r < this._rows;
    }
}


